__registerContent("quickrecall/history/gg-viceroys", {"notes":{"qr-gg-viceroys":{"source":"Modern History","sections":[{"type":"points","title":"🎯 The Three Phases","items":["1773: the office of Governor-General of Bengal was created (Regulating Act) — first holder Warren Hastings","1833: the designation was changed to Governor-General of India (Charter Act 1833) — first holder Lord William Bentinck","After the Revolt of 1857, the Governor-General also became the Viceroy (Government of India Act, 1858) — first Viceroy Lord Canning"]},{"type":"table","title":"🏛 Governors-General of Bengal (1773–1833) & Key Events","headers":["Governor-General","Major Events"],"rows":[["Warren Hastings (1773–85)","Regulating Act 1773; Supreme Court at Calcutta (1774); Pitt's India Act 1784; Asiatic Society of Bengal (1784); First Anglo-Maratha War / Treaty of Salbai 1782"],["Lord Cornwallis (1786–93)","Permanent Settlement 1793; civil-service reforms; Third Anglo-Mysore War / Treaty of Seringapatam 1792"],["Sir John Shore (1793–98)","Charter Act 1793; Policy of Non-Intervention; Battle of Kharda (1795)"],["Lord Wellesley (1798–1805)","Subsidiary Alliance system; Fourth Anglo-Mysore War (1799); Fort William College, Calcutta (1800)"],["Lord Minto I (1807–13)","Treaty of Amritsar with Ranjit Singh (1809); Charter Act 1813"],["Lord Hastings (1813–23)","End of Non-Intervention; Third Anglo-Maratha War (1817–18)"],["Lord Amherst (1823–28)","First Anglo-Burmese War; Treaty of Yandabo (1826)"],["Lord William Bentinck (1828–33)","Charter Act 1833; Abolition of Sati (1829); suppression of Thuggee; English Education (Macaulay's Minute 1835)"]]},{"type":"table","title":"🗺 Governors-General of India (1833–1858)","headers":["Governor-General","Major Events"],"rows":[["Lord William Bentinck (1833–35)","First Governor-General of India"],["Lord Hardinge I (1844–48)","First Anglo-Sikh War (1845–46); Treaty of Lahore"],["Lord Dalhousie (1848–56)","Doctrine of Lapse; Second Anglo-Sikh War; annexation of Punjab & Awadh (1856); first railway (Bombay–Thane, 1853); first telegraph line; Wood's Despatch (1854)"],["Lord Canning (1856–62)","Last GG under Company rule; became the FIRST Viceroy after 1858"]]},{"type":"table","title":"👑 Viceroys of India (1858–1947) & Key Events","headers":["Viceroy","Major Events"],"rows":[["Lord Canning (1858–62)","First Viceroy; Revolt of 1857 ended; Indian Councils Act 1861"],["Lord Mayo (1869–72)","Financial decentralisation; first census attempt (1872); only Viceroy assassinated (in the Andamans)"],["Lord Lytton (1876–80)","Vernacular Press Act 1878; Arms Act 1878; Second Anglo-Afghan War; Delhi Durbar 1877"],["Lord Ripon (1880–84)","Local Self-Government (1882); repealed Vernacular Press Act; Ilbert Bill controversy; first regular census (1881)"],["Lord Dufferin (1884–88)","Indian National Congress founded (1885)"],["Lord Lansdowne (1888–94)","Indian Councils Act 1892; Age of Consent Act 1891; Durand Line (1893)"],["Lord Curzon (1899–1905)","Partition of Bengal (1905); Indian Universities Act 1904; Ancient Monuments Preservation Act 1904"],["Lord Minto II (1905–10)","Morley-Minto Reforms 1909; separate electorates introduced"],["Lord Hardinge II (1910–16)","Capital shifted Calcutta → Delhi (1911); Delhi Durbar 1911"],["Lord Chelmsford (1916–21)","Government of India Act 1919; Jallianwala Bagh (1919); Non-Cooperation began; Rowlatt Act"],["Lord Reading (1921–26)","Chauri Chaura (1922); Swaraj Party formed (1923)"],["Lord Irwin (1926–31)","Simon Commission; Civil Disobedience / Dandi March; Gandhi-Irwin Pact (1931)"],["Lord Willingdon (1931–36)","Second/Third Round Table Conferences; Government of India Act 1935"],["Lord Linlithgow (1936–44)","World War II; Quit India Movement (1942); Cripps Mission (1942); longest-serving Viceroy"],["Lord Wavell (1944–47)","Wavell Plan; Simla Conference (1945); Cabinet Mission (1946)"],["Lord Mountbatten (1947)","Last Viceroy; Indian Independence Act; Independence on 15 August 1947; first GG of independent India"]]},{"type":"traps","title":"⚠ Prelims Traps (Important One-Liners)","items":[{"label":"The 'firsts' and 'lasts'","lines":["First GG of Bengal: Warren Hastings; First GG of India: Lord William Bentinck.","Last GG under Company & First Viceroy: Lord Canning.","Last Viceroy of British India & First GG of independent India: Lord Mountbatten.","First (and only) Indian & last GG of independent India: C. Rajagopalachari."]},{"label":"Event-Viceroy confusions","lines":["Partition of Bengal (1905): Curzon; capital shift to Delhi (1911): Hardinge II.","INC founded (1885): under Dufferin; Jallianwala Bagh (1919): Chelmsford.","Quit India (1942): Linlithgow (longest-serving Viceroy)."]},{"label":"Reforms mapping","lines":["Morley-Minto Reforms 1909 → Minto II (separate electorates).","Montagu-Chelmsford / GoI Act 1919 → Chelmsford.","Total Viceroys (1858–1947) = 18."]}]},{"type":"recall","title":"🔑 Quick Recall","items":["1773 GG of Bengal → 1833 GG of India → 1858 Viceroy","Warren Hastings (1st GG Bengal); Bentinck (1st GG India); Canning (1st Viceroy)","Dalhousie: Doctrine of Lapse, first railway (1853)","Curzon: Partition of Bengal (1905)","Ripon: Local Self-Government (Father of Local Self-Govt in India)","Mountbatten: last Viceroy; Independence 15 Aug 1947","Total Viceroys 1858–1947 = 18"]}]}},"quizzes":{"qr-gg-viceroys":{"title":"Governors-General & Viceroys of India","questions":[{"q":"Who was the first Governor-General of Bengal?","options":["Lord Clive","Warren Hastings","Lord Cornwallis","Lord William Bentinck"],"correct":1,"explain":"Warren Hastings became the first Governor-General of Bengal under the Regulating Act of 1773."},{"q":"The designation was changed from Governor-General of Bengal to Governor-General of India by which Act, and who was the first to hold this title?","options":["Charter Act 1793; Sir John Shore","Charter Act 1833; Lord William Bentinck","Government of India Act 1858; Lord Canning","Regulating Act 1773; Warren Hastings"],"correct":1,"explain":"The Charter Act of 1833 created the office of Governor-General of India; Lord William Bentinck was the first to hold it."},{"q":"Who was the first Viceroy of India?","options":["Lord Mayo","Lord Canning","Lord Ripon","Lord Dalhousie"],"correct":1,"explain":"Lord Canning became the first Viceroy of India after the Government of India Act, 1858."},{"q":["Consider the following statements about Lord Dalhousie:","I. He introduced the Doctrine of Lapse.","II. India's first railway line (Bombay–Thane) was opened during his tenure (1853).","Which of the statements given above is/are correct?"],"options":["I only","II only","Both I and II","Neither I nor II"],"correct":2,"explain":"Both are correct — Dalhousie is associated with the Doctrine of Lapse and the first railway line (Bombay–Thane, 1853)."},{"q":"The Partition of Bengal (1905) took place during the tenure of:","options":["Lord Minto II","Lord Curzon","Lord Hardinge II","Lord Ripon"],"correct":1,"explain":"The Partition of Bengal was carried out in 1905 under Viceroy Lord Curzon."},{"q":["Match the Viceroy with the event:","I. Lord Dufferin — a) Capital shifted to Delhi","II. Lord Hardinge II — b) INC founded","III. Lord Chelmsford — c) Jallianwala Bagh massacre","Select the correct answer:"],"options":["I-b, II-a, III-c","I-a, II-b, III-c","I-c, II-a, III-b","I-b, II-c, III-a"],"correct":0,"explain":"INC was founded (1885) under Dufferin (b); the capital shifted to Delhi (1911) under Hardinge II (a); Jallianwala Bagh (1919) occurred under Chelmsford (c)."},{"q":"The Local Self-Government resolution (1882) that earned the title 'Father of Local Self-Government in India' is associated with:","options":["Lord Lytton","Lord Ripon","Lord Mayo","Lord Curzon"],"correct":1,"explain":"Lord Ripon's 1882 resolution on local self-government earned him the title 'Father of Local Self-Government in India'."},{"q":"Which Viceroy was assassinated during his tenure?","options":["Lord Mayo","Lord Lytton","Lord Dufferin","Lord Reading"],"correct":0,"explain":"Lord Mayo was assassinated in 1872 in the Andaman Islands — the only Viceroy to be assassinated in office."},{"q":"The Vernacular Press Act (1878) and the Arms Act (1878) were passed under which Viceroy?","options":["Lord Ripon","Lord Lytton","Lord Lansdowne","Lord Minto II"],"correct":1,"explain":"Both the Vernacular Press Act and the Arms Act (1878) were enacted under Lord Lytton (Ripon later repealed the Vernacular Press Act)."},{"q":"The Morley-Minto Reforms (1909), which introduced separate electorates, are associated with which Viceroy?","options":["Lord Minto II","Lord Curzon","Lord Chelmsford","Lord Hardinge II"],"correct":0,"explain":"The Morley-Minto Reforms (Indian Councils Act 1909) were introduced under Lord Minto II and brought in separate electorates."},{"q":"Who was the last Governor-General of India under Company rule?","options":["Lord Dalhousie","Lord Canning","Lord Mayo","Lord Ripon"],"correct":1,"explain":"Lord Canning was the last Governor-General under Company rule and then became the first Viceroy after 1858."},{"q":["Consider the following statements:","I. Lord Mountbatten was the last Viceroy of British India.","II. He was also the first Governor-General of independent India.","Which of the statements given above is/are correct?"],"options":["I only","II only","Both I and II","Neither I nor II"],"correct":2,"explain":"Both are correct — Mountbatten was the last Viceroy and the first Governor-General of independent India."},{"q":"The Quit India Movement (1942) occurred during the tenure of which Viceroy, who was also the longest-serving Viceroy?","options":["Lord Willingdon","Lord Linlithgow","Lord Wavell","Lord Irwin"],"correct":1,"explain":"The Quit India Movement (1942) occurred under Lord Linlithgow, the longest-serving Viceroy (1936–1944)."},{"q":"The Permanent Settlement (1793) was introduced by:","options":["Warren Hastings","Lord Cornwallis","Lord Wellesley","Sir John Shore"],"correct":1,"explain":"Lord Cornwallis introduced the Permanent Settlement of Bengal in 1793."},{"q":"The Subsidiary Alliance system was introduced by which Governor-General?","options":["Lord Wellesley","Lord Hastings","Lord Cornwallis","Lord Dalhousie"],"correct":0,"explain":"Lord Wellesley introduced the Subsidiary Alliance system (1798) to expand British control."},{"q":["Arrange the following in chronological order of their tenures:","1. Lord Curzon","2. Lord Ripon","3. Lord Dalhousie","Select the correct order (earliest first):"],"options":["3 → 2 → 1","1 → 2 → 3","2 → 3 → 1","3 → 1 → 2"],"correct":0,"explain":"Dalhousie (1848–56) → Ripon (1880–84) → Curzon (1899–1905)."},{"q":"The Gandhi-Irwin Pact (1931) was signed during the tenure of Viceroy:","options":["Lord Reading","Lord Irwin","Lord Willingdon","Lord Linlithgow"],"correct":1,"explain":"The Gandhi-Irwin Pact (1931) was signed during Lord Irwin's tenure, during the Civil Disobedience period."},{"q":"The abolition of Sati (1829) and the suppression of Thuggee are associated with:","options":["Lord William Bentinck","Lord Cornwallis","Lord Dalhousie","Warren Hastings"],"correct":0,"explain":"Lord William Bentinck abolished Sati (1829) and suppressed Thuggee; he was also the first GG of India."},{"q":"The total number of Viceroys who governed India between 1858 and 1947 was:","options":["16","18","20","22"],"correct":1,"explain":"There were 18 Viceroys of India from 1858 (Canning) to 1947 (Mountbatten)."},{"q":"Who was the first and only Indian to serve as Governor-General of India (of independent India)?","options":["Dr. Rajendra Prasad","C. Rajagopalachari","Jawaharlal Nehru","Sardar Vallabhbhai Patel"],"correct":1,"explain":"C. Rajagopalachari was the first and only Indian Governor-General (and the last GG) of independent India."}]}}});
